package com.angussoftware.letta.env

import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * 0.4.35 content keying (todo 04084c92d9f4): the extraction marker carries
 * the rootfs.tar sha it was extracted from, closing the
 * same-versionCode/different-tar rebuild gap — versionCode keying (0.4.34)
 * cannot see a tar content swap inside one build number.
 *
 * Contract axis 1: parseRootfsTarSha reads the generator-stamped authority
 * line from the integrity manifest.
 * Contract axis 2: isMarkerContentStale decides staleness on content —
 * the marker must CONTAIN the expected sha.
 */
class RootfsMarkerContentKeyingTest {

    private val sha = "78d4135a33a84c716c5e222435b5f612c44ad73ce15101ea19c291a49e23072c"

    // ---- parseRootfsTarSha ----

    @Test
    fun parses_generator_stamped_authority_line() {
        val manifest = """
            # integrity-manifest v1 — GENERATED by tools/integrity/generate-manifest.py; do not hand-edit
            # authority: this APK's assets. dest<TAB>sha256<TAB>source<TAB>[tar-member]
            # rootfs.tar authority sha256 at generation: $sha
            # provenance: rootfs.tar[./usr/lib/aarch64-linux-gnu/libc.so.6]
        """.trimIndent()
        assertEquals(sha, LettaEnvironmentService.parseRootfsTarSha(manifest))
    }

    @Test
    fun absent_header_yields_null() {
        // Pre-generator manifests carry no authority line — content keying
        // must go inert (version keying alone governs), never crash.
        assertNull(LettaEnvironmentService.parseRootfsTarSha("# letta.js pin-version: 0.34.4\n"))
        assertNull(LettaEnvironmentService.parseRootfsTarSha(""))
    }

    @Test
    fun malformed_sha_yields_null() {
        // Truncated / non-hex values never become a staleness key.
        assertNull(
            LettaEnvironmentService.parseRootfsTarSha(
                "# rootfs.tar authority sha256 at generation: not-a-hash"
            )
        )
        assertNull(
            LettaEnvironmentService.parseRootfsTarSha(
                "# rootfs.tar authority sha256 at generation: 78d4135a"
            )
        )
    }

    // ---- isMarkerContentStale ----

    @Test
    fun marker_carrying_current_sha_is_fresh() {
        assertFalse(LettaEnvironmentService.isMarkerContentStale(sha, sha))
        // Content may carry more than the bare sha — containment, not equality.
        assertFalse(LettaEnvironmentService.isMarkerContentStale("extracted-from:$sha v2", sha))
    }

    @Test
    fun marker_with_different_sha_is_stale() {
        // Hotfix rebuild under the same versionCode: new tar, new sha, old
        // marker content — must re-extract.
        val other = "0".repeat(63) + "1"
        assertTrue(LettaEnvironmentService.isMarkerContentStale(other, sha))
    }

    @Test
    fun pre_content_stamp_marker_migrates_once() {
        // 0.4.34-form markers are EMPTY files (createNewFile): content
        // missing = stale, so the first 0.4.35 boot re-extracts once and
        // stamps the sha. Steady state thereafter.
        assertTrue(LettaEnvironmentService.isMarkerContentStale("", sha))
    }

    @Test
    fun unreadable_marker_reads_as_stale() {
        // runCatching-null marker content (IO error, dir collision): the
        // safe direction is re-extract, not trust.
        assertTrue(LettaEnvironmentService.isMarkerContentStale(null, sha))
    }

    @Test
    fun no_expected_sha_disables_content_axis() {
        // Old manifest (no authority header): content staleness is inert —
        // exactly the 0.4.34 semantics; version keying alone decides.
        assertFalse(LettaEnvironmentService.isMarkerContentStale("anything", null))
        assertFalse(LettaEnvironmentService.isMarkerContentStale(null, null))
    }
}
